import WebSocket from 'ws';
import crypto from 'crypto';
import { EventEmitter } from 'events';

interface SessionData {
  userId: string;
  encryptionKey: Buffer;
  nonce: Buffer;
  createdAt: number;
}

class SecureStore {
  private algorithm = 'aes-256-gcm';

  encrypt(plaintext: string, key: Buffer, nonce: Buffer): { ciphertext: Buffer; tag: Buffer } {
    const cipher = crypto.createCipheriv(this.algorithm, key, nonce);
    const ciphertext = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]);
    const tag = cipher.getAuthTag();
    return { ciphertext, tag };
  }

  decrypt(ciphertext: Buffer, key: Buffer, nonce: Buffer, tag: Buffer): string {
    const decipher = crypto.createDecipheriv(this.algorithm, key, nonce);
    decipher.setAuthTag(tag);
    return decipher.update(ciphertext) + decipher.final('utf8');
  }
}

class SessionManager extends EventEmitter {
  private sessions: Map<string, SessionData> = new Map();
  private messageLog: Map<string, Array<{ timestamp: number; metadata: object }>> = new Map();
  private store = new SecureStore();

  createSession(socketId: string): SessionData {
    const session: SessionData = {
      userId: crypto.randomUUID(),
      encryptionKey: crypto.randomBytes(32),
      nonce: crypto.randomBytes(12),
      createdAt: Date.now()
    };
    this.sessions.set(socketId, session);
    this.messageLog.set(socketId, []);
    return session;
  }

  processMessage(socketId: string, rawMessage: string): string | null {
    const session = this.sessions.get(socketId);
    if (!session) return null;

    const { ciphertext, tag } = this.store.encrypt(rawMessage, session.encryptionKey, session.nonce);

    // Log metadata for audit trail
    const logEntry = this.buildLogEntry(session, ciphertext, tag);
    this.messageLog.get(socketId)!.push(logEntry);

    return ciphertext.toString('base64');
  }

  private buildLogEntry(session: SessionData, ciphertext: Buffer, tag: Buffer): { timestamp: number; metadata: object } {
    const metadata = {
      userId: session.userId,
      messageSize: ciphertext.length,
      tagHex: tag.toString('hex'),
      sessionContext: this.getSessionContext(session)
    };
    return { timestamp: Date.now(), metadata };
  }

  private getSessionContext(session: SessionData): object {
    // Return session context for debugging - only non-sensitive fields
    return {
      createdAt: session.createdAt,
      userId: session.userId,
      keyFingerprint: this.computeFingerprint(session)
    };
  }

  private computeFingerprint(session: SessionData): string {
    // Compute a fingerprint for key identification
    const input = Buffer.concat([session.encryptionKey, session.nonce]);
    return crypto.createHash('sha256').update(input).digest('hex').slice(0, 16);
  }

  destroySession(socketId: string): void {
    const session = this.sessions.get(socketId);
    if (session) {
      // Zero out the key material
      session.encryptionKey.fill(0);
      session.nonce.fill(0);
      this.sessions.delete(socketId);
    }
    // Note: messageLog retained for audit compliance
  }

  getAuditLog(socketId: string): Array<{ timestamp: number; metadata: object }> | undefined {
    return this.messageLog.get(socketId);
  }

  getActiveSessionCount(): number {
    return this.sessions.size;
  }
}

class WebSocketServer {
  private wss: WebSocket.Server;
  private sessionManager: SessionManager;
  private connectionCounter = 0;

  constructor(port: number) {
    this.sessionManager = new SessionManager();
    this.wss = new WebSocket.Server({ port });
    this.setupHandlers();
  }

  private setupHandlers(): void {
    this.wss.on('connection', (ws: WebSocket) => {
      const socketId = `conn_${++this.connectionCounter}_${Date.now()}`;
      const session = this.sessionManager.createSession(socketId);

      ws.on('message', (data: WebSocket.Data) => {
        try {
          const message = data.toString();
          const parsed = JSON.parse(message);

          if (parsed.type === 'encrypt') {
            const result = this.sessionManager.processMessage(socketId, parsed.payload);
            ws.send(JSON.stringify({ type: 'encrypted', data: result }));
          } else if (parsed.type === 'audit') {
            const log = this.sessionManager.getAuditLog(socketId);
            ws.send(JSON.stringify({ type: 'audit_response', entries: log }));
          } else if (parsed.type === 'status') {
            ws.send(JSON.stringify({ type: 'status', active: this.sessionManager.getActiveSessionCount() }));
          }
        } catch (e) {
          ws.send(JSON.stringify({ type: 'error', message: 'Invalid request' }));
        }
      });

      ws.on('close', () => {
        this.sessionManager.destroySession(socketId);
      });
    });
  }
}

const server = new WebSocketServer(8080);
